 p('ornaments','tension-mobile','細い糸に吊られた四つの輪が、ホバーで静かに広がる。','${position:relative;display:block;width:100%;min-height:200px;--or-play:running}$.sop-ornament .or-stage{display:grid;place-items:center;min-height:200px}$.sop-ornament .tm-bar{position:relative;width:190px;height:150px;border-top:1px solid #9daec0;transform:rotate(-5deg);transition:transform .9s cubic-bezier(.2,.8,.2,1)}$.sop-ornament .tm-bar span{position:absolute;top:0;left:calc(var(--i)*44px + 17px);width:1px;height:calc(42px + var(--i)*18px);background:#778e9d;transform-origin:top;transform:rotate(calc(-8deg + var(--i)*6deg));transition:transform .9s}$.sop-ornament .tm-bar span:after{content:"";position:absolute;left:-12px;bottom:-24px;width:25px;height:25px;border:2px solid #a6c6c4;border-left-color:#688596;border-radius:50%;box-shadow:inset 0 0 0 1px #d5e4d433}$.sop-ornament:hover .tm-bar{transform:rotate(4deg)}$.sop-ornament:hover .tm-bar span{transform:rotate(calc(-19deg + var(--i)*13deg))}',markup='<div class="sop-ornament sop-$" data-ornament="$"><div class="or-stage" aria-hidden="true"><div class="tm-bar"><span style="--i:0"></span><span style="--i:1"></span><span style="--i:2"></span><span style="--i:3"></span></div></div></div>')
